message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR_EXECUTION_FAILURE",
      "definition": "A subsequent agent action attempts to resolve a failure identified during an earlier execution step by modifying the failed operation or its parameters.",
      "source_description": "An earlier observed execution failure that reports an error or invalid usage.",
      "target_description": "A subsequent agent action intended to correct or work around that failure."
    },
    {
      "name": "DERIVES_TASK_RELEVANT_INFORMATION_FROM_OBSERVATION",
      "definition": "The agent analyzes an earlier observed execution result to extract task-relevant information such as document classification, field values, or content meaning.",
      "source_description": "An earlier observation containing raw or extracted content produced by a tool call.",
      "target_description": "A subsequent agent analysis or decision that extracts or interprets task-relevant information from that observation."
    },
    {
      "name": "USES_PRIOR_OBSERVATION_TO_SELECT_NEXT_ACTION",
      "definition": "The agent chooses its next processing action based on the content or state revealed by a prior observation.",
      "source_description": "An earlier observation that provides context, reveals remaining work, or indicates what to inspect next.",
      "target_description": "A subsequent agent action selected to continue or advance the task based on that observation."
    },
    {
      "name": "REQUESTS_OMITTED_CONTENT_FROM_PARTIAL_OBSERVATION",
      "definition": "An earlier observation reveals only a partial or summarized view of available content, prompting the agent to retrieve the omitted or more detailed content needed for task processing.",
      "source_description": "An earlier observation that provides incomplete content, such as only a limited portion of one or more files.",
      "target_description": "A subsequent retrieval action that requests the remaining, fuller, or more detailed content."
    },
    {
      "name": "CONTINUES_WITH_REMAINING_ITEMS_AFTER_PARTIAL_PROCESSING",
      "definition": "After processing or observing a subset of a collection, the agent proceeds to process the remaining unprocessed items.",
      "source_description": "An observation or analysis indicating that only part of a collection has been examined or processed.",
      "target_description": "A subsequent action targeting the remaining unprocessed items in that collection."
    },
    {
      "name": "RESOLVES_FIELD_VALUE_CONFLICT_PER_INSTRUCTION",
      "definition": "The agent encounters an observed document containing multiple conflicting candidate values for a field and decides which value to use according to an explicit user instruction.",
      "source_description": "An observation containing conflicting field values from a document.",
      "target_description": "A subsequent agent decision selecting the value prescribed by the user instruction."
    }
  ]
}

